// Lattice Mirror - color only, ANIMATED. Runs INSIDE shadeSurface().
// The object becomes a mirror flying through an endless lattice of beams that
// vibrate like plucked strings. For every pixel the view ray is reflected on the
// surface (real normal, so a displaced or bumpy object reflects accordingly) and
// marched through the lattice: the color is the beam it meets, fogged with
// distance, plus the glow of the beams it passes close to.
// This is a SMALL ray march inside the texture: 48 steps, once per pixel (not in
// map()), so it stays cheap even at high resolution.
// In scope: pModel, n_model, viewDir_model, t.
// Dock colors: u_col1 = beams and glow, u_col2 = the deep background.

float BEAM  = 0.045 * max(E, 0.05);  // slider E   // beam radius (cells)   [0.01 .. 0.15]
float SPEED = 0.6 * F;               // slider F   // flight speed          [0 .. 3]
float SWING = 0.05;    // amplitude of the vibration (cells)                 [0 .. 0.12]
float FOG   = 0.18;    // how fast the lattice fades with distance           [0.05 .. 0.5]
const int STEPS = 48;

vec3 R  = reflect(-viewDir_model, n_model);
vec3 ro = vec3(0.5, 0.5, SPEED * t) + pModel * 0.5;   // the mirror flies along z

float tm = 0.0;
float glow = 0.0;
float hitD = 1e9;
for (int i = 0; i < STEPS; i++) {
    vec3 qp = ro + R * tm;
    vec3 c  = fract(qp) - 0.5;
    vec3 id = floor(qp);
    // each beam is displaced by a wave running along it (plucked string)
    vec2 wx = SWING * vec2(sin(6.2832 * qp.x + 3.0 * t + 1.7 * id.y), cos(6.2832 * qp.x + 2.3 * t + 1.3 * id.z));
    vec2 wy = SWING * vec2(sin(6.2832 * qp.y + 2.7 * t + 1.1 * id.z), cos(6.2832 * qp.y + 3.1 * t + 0.9 * id.x));
    vec2 wz = SWING * vec2(sin(6.2832 * qp.z + 2.5 * t + 1.9 * id.x), cos(6.2832 * qp.z + 2.9 * t + 0.7 * id.y));
    float bx = length(c.yz + wx) - BEAM;
    float by = length(c.zx + wy) - BEAM;
    float bz = length(c.xy + wz) - BEAM;
    float d = min(bx, min(by, bz));
    glow += exp(-max(d, 0.0) * 40.0) * exp(-FOG * tm) * 0.05;
    if (d < 0.002) { hitD = tm; break; }
    tm += max(d * 0.7, 0.01);    // 0.7: the vibration makes d a little optimistic
    if (tm > 14.0) break;
}

vec3 col = ubuf.u_col2;
if (hitD < 1e8) {
    float fog = exp(-FOG * hitD);
    // beams shaded by how squarely the reflected ray meets them (cheap fake light)
    col = mix(ubuf.u_col2, ubuf.u_col1 * (0.55 + 0.45 * fog), fog);
}
col += ubuf.u_col1 * glow;
// Fresnel: grazing angles reflect more, facing angles show more of the deep tone
float fres = 0.35 + 0.65 * pow(1.0 - max(dot(n_model, viewDir_model), 0.0), 2.0);
col = mix(ubuf.u_col2 * 0.6, col, fres);

textureCol = col;
